import React from 'react';
import JobItem from './JobItem';

const JobList = ({ jobs, fetchJobs }) => {
    return (
        <div>
            {jobs.map(job => (
                <JobItem key={job._id} job={job} fetchJobs={fetchJobs} />
            ))}
        </div>
    );
};

export default JobList;
